    [431758] = { en = "Engrave your bracers with the Immolation Aura rune:\r\n\r\n$@spellicon431757\r\n$@spelldesc427726", description = "Incidi i tuoi bracciali con la runa Aura d'Immolation:\r\n\r\n$@spellicon431757\r\n$@spelldesc427726" },
    [432042] = { en = "When you cast Chain Heal or Riptide you gain $s1 charges of Tidal Waves, which reduces the cast time of your Healing Wave by $432041s1%, reduces the cast time of your Chain Heal by $432041s3%, and increases the critical effect chance of your Lesser Healing Wave by $432041s2%.", description = "Quando lanci Catena di Guarigione o Flusso di Marea, ottieni $s1 cariche di Onde di Marea, che riducono il tempo di lancio di Onda di Guarigione del $432041s1%, riducono il tempo di lancio di Catena di Guarigione del $432041s3% e aumentano la probabilità di effetto critico di Onda di Guarigione Inferiore del $432041s2%." },
    [432056] = { en = "Lightning Bolt and Chain Lightning have a $h% chance to add an additional charge to your active Lightning Shield, up to a maximum of $s1 Charges.\r\n\r\nEarth Shock now releases all Lightning Shield charges above $s2, dealing their damage to the target, and energizing you for $s3% of your maximum mana per charge released.", description = "Dardo Fulminante e Catena di Fulmini hanno una probabilità del $h% di aggiungere una carica aggiuntiva al tuo Scudo Fulminante attivo, fino a un massimo di $s1 cariche.\r\n\r\nImpatto Terrestre ora rilascia tutte le cariche dello Scudo Fulminante oltre $s2, infliggendo i relativi danni al bersaglio e rigenerando il $s3% del tuo mana massimo per ogni carica rilasciata." },
    [432134] = { en = "Your Lightning Shield now has ${$m1+3} charges, and your melee attacks have a $h% chance (${$h/2}% chance while dual-wielding) to trigger one of those charges, immediately damaging your target.", description = "Il tuo Scudo Fulminante ora ha ${$m1+3} cariche e i tuoi attacchi in mischia hanno una probabilità del $h% (probabilità del ${$h/2}% con due armi) di attivare una di queste cariche, danneggiando immediatamente il bersaglio." },
