    [432139] = { en = "Permanently enchants a shoulder slot item to increase your attack speed by $432137s1%.", description = "Incanta permanentemente un oggetto per la spalla, aumentando la velocità d'attacco del $432137s1%." },
    [432140] = { en = "Your Lightning Shield never loses charges, now has a $m2 sec cooldown, and deals damage to all enemies within $432143a1 yards.", description = "Il tuo Scudo Fulminante non perde mai cariche, ora ha un tempo di recupero di $m2 sec e infligge danni a tutti i nemici entro $432143a1 metri." },
