    [432256] = { en = "You gain $432255s1 Energy every time you deal a melee or ranged critical strike.", description = "Ottieni $432255s1 energia ogni volta che infliggi un colpo critico in mischia o a distanza." },
    [432259] = { en = "You have a $m1% chance to gain $432260s1 Energy every time you deal melee damage with your off-hand weapon.", description = "Hai una probabilità del $m1% di ottenere $432260s1 energia ogni volta che infliggi danni in mischia con la tua arma secondaria." },
    [432271] = { en = "Your Eviscerate and Envenom abilities refresh either your Slice and Dice or your Blade Dance duration to its 5 combo point maximum. If both are active, only the one with shortest remaining duration will be refreshed.", description = "Le abilità Eviscerazione e Avvelenamento rinnovano la durata di Affettamento o Danza delle Lame fino al massimo di 5 punti combo. Se entrambi gli effetti sono attivi, verrà rinnovato solo quello con la durata residua più breve." },
    [432273] = { en = "Whenever you dodge or parry an attack you gain an Unfair Advantage, striking back for $432274s2% of your main hand weapon's damage and gaining $432274s3 combo $lpoint:points;. This cannot occur more than once per second.", description = "Ogni volta che schivi o pari un attacco, ottieni un Vantaggio Sleale e contrattacchi infliggendo il $432274s2% dei danni della tua arma nella mano principale e ottenendo $432274s3 $lpunto:punti combo;. Questo effetto può verificarsi al massimo una volta al secondo." },
    [432276] = { en = "Your abilities deal $432275s1% increased damage to targets afflicted by one of your Bleed effects. Your Rupture also heals you for $s2% of the damage it deals.", description = "Le tue abilità infliggono il $432275s1% di danni in più ai bersagli affetti da uno dei tuoi effetti di Sanguinamento. Inoltre, la tua Rottura ti cura per una quantità pari al $s2% dei danni inflitti." },
