    [433100] = { en = "A sweeping attack that strikes all enemies in front of you for $s2% weapon damage.", description = "Un attacco ad ampio raggio che colpisce tutti i nemici di fronte a te e infligge il $s2% dei danni dell'arma." },
    [433107] = { en = "While you are in Cat Form, Bear Form, or Dire Bear Form, party members within $407975a1 yards gain increased combat ferocity.  Each melee hit has a $407975h% chance of granting the attacker an extra attack with $407975s1% additional Attack Power. No effect if the party member is already benefitting from Windfury Totem.\r\n", description = "Quando sei in Forma Felina, Forma d'Orso o Forma d'Orso Ferino, i membri del gruppo entro $407975a1 metri ottengono una ferocia maggiore in combattimento. Ogni colpo in mischia ha una probabilità del $407975h% di concedere all'attaccante un attacco aggiuntivo con il $407975s1% di potenza d'attacco in più. Non ha effetto se il membro del gruppo beneficia già del Totem della Furia del Vento.\r\n" },
    [433251] = { en = "Electrocutioner 6000 unleashes a blast of lightning at the furthest target, inflicting $s1 Nature damage and leaping up to $x times.  Each player hit by this effect takes $s2% increased damage from $@spellname433251 for $d.", description = "Electrocutioner 6000 scatena una scarica di fulmini contro il bersaglio più lontano, infliggendo $s1 danni da natura e balzando fino a $x volte. Ogni giocatore colpito da questo effetto subisce il $s2% di danni in più da $@spellname433251 per $d." },
    [433359] = { en = "Electrocutioner 6000 changes the pollarity of the target causing them to pull in players within $433363A1 yards every $s3 sec, and inflicting $433363s1 Nature damage.", description = "Electrocutioner 6000 cambia la polarità del bersaglio, attirando a sé i giocatori entro $433363A1 metri ogni $s3 sec e infliggendo $433363s1 danni da natura." },
    [433363] = { en = "$@spelldesc433359", description = "$@spelldesc433359" },
    [433398] = { en = "Electrocutioner 6000 unleashes a pulse of electricity inflicting $s1 Nature damage, knocking all players away.", description = "Electrocutioner 6000 scatena un impulso elettrico che infligge $s1 danni da natura e respinge tutti i giocatori." },
    [433521] = { en = "Grants several improvements to your poisons:\r\n\r\nWhen you inflict any other poison on a target, you also inflict Deadly Poison.\r\n\r\nIf your weapon does not have a poison applied, it has a chance to trigger Instant Poison as if Instant Poison were applied.\r\n\r\nDeadly Poison and Instant Poison now gain increased damage from your Attack Power.", description = "Conferisce diversi miglioramenti ai tuoi veleni:\r\n\r\nQuando applichi qualsiasi altro veleno a un bersaglio, applichi anche Veleno Mortale.\r\n\r\nSe la tua arma non ha un veleno applicato, ha una probabilità di attivare Veleno Istantaneo come se fosse applicato.\r\n\r\nVeleno Mortale e Veleno Istantaneo ora ottengono un bonus ai danni dalla tua potenza d'attacco." },
    [433546] = { en = "The caster unleashes a wave of toxic slime at all players, inflicting $s1 Nature damage and an additional $s2 Nature damage every $t2 sec for $d.  This effect stacks.", description = "L'incantatore scatena un'ondata di melma tossica contro tutti i giocatori, infliggendo $s1 danni Natura e altri $s2 danni Natura ogni $t2 sec per $d. Questo effetto si accumula." },
    [434358] = { en = "Viscous Fallout oozes forth $s1 Toxic Slime.", description = "Viscous Fallout fa fuoriuscire $s1 melma tossica." },
    [434398] = { en = "$@spelldesc434399", description = "$@spelldesc434399" },
    [434399] = { en = "The Irradiated Goo unleashes a pulse of ionizing radiation that inflicts $434398s1 Nature damage every $t1 sec.", description = "La Melma Irradiata scatena un impulso di radiazioni ionizzanti che infligge $434398s1 danni Natura ogni $t1 sec." },
    [434433] = { en = "Viscous Fallout creates a pool of toxic slime that inflicts $s1 Nature damage every $t sec to players standing within it.  \r\n\r\nIn addition, players in the effect also have their movement speed reduced by $s2%.", description = "Viscous Fallout crea una pozza di melma tossica che infligge $s1 danni Natura ogni $t sec ai giocatori che vi sostano.  \r\n\r\nInoltre, la velocità di movimento dei giocatori colpiti dall'effetto è ridotta del $s2%." },
    [434434] = { en = "$@spelldesc434433", description = "$@spelldesc434433" },
    [434488] = { en = "Melee attacks deal an additional 7 Fire damage for $d.", description = "Gli attacchi in mischia infliggono 7 danni da Fuoco aggiuntivi per $d." },
    [435168] = { en = "A protective mana shield surrounds the caster absorbing 250 damage. While the shield holds, increases mana regeneration by $s2 every $t2 sec for $d.", description = "Uno scudo protettivo di mana avvolge l'incantatore, assorbendo 250 danni. Finché lo scudo regge, la rigenerazione del mana aumenta di $s2 ogni $t2 sec per $d." },
    [435359] = { en = "Increases armor by $s1, but movement speed is reduced by $s2%. Effect cannot be removed and lasts for $d.", description = "Aumenta l'armatura di $s1, ma riduce la velocità di movimento del $s2%. L'effetto non può essere rimosso e dura $d." },
    [435360] = { en = "+$s1 Attack Power against Mechanical units.", description = "+$s1 potenza d'attacco contro le unità meccaniche." },
    [435481] = { en = "Permanently enchant a Weapon to cause all spells and attacks to sometimes deal $439164s1 additional damage to mechanical creatures.", description = "Incanta permanentemente un'arma, facendo sì che tutti gli incantesimi e gli attacchi infliggano talvolta $439164s1 danni aggiuntivi alle creature meccaniche." },
    [435563] = { en = "Increases your Comprehension skill by $s1 for $d.", description = "Aumenta la tua abilità di Comprensione di $s1 per $d." },
    [435849] = { en = "Conjure $s1 Comprehension Charms.", description = "Crea $s1 amuleti di Comprensione." },
    [435900] = { en = "Increase attack speed by $435899s1%.  You may be able to push this experiment further.....", description = "Aumenta la velocità d'attacco del $435899s1%. Potresti riuscire a spingere oltre questo esperimento....." },
    [435903] = { en = "Teaches you how to permanently enchant a piece of chest armor to reflect 9 damage back to the attacker when the bearer is struck in Melee.\r\n", description = "Ti insegna a incantare permanentemente un pezzo di armatura per il torso affinché infligga 9 danni all'attaccante quando chi la indossa viene colpito in mischia.\r\n" },
