    [435963] = { en = "Inflicts $s1 fire damage to those in the blast radius plus an additional $443813s1 nature damage every 2 sec for 10 seconds. Also reduces the movement speed of affected targets by 25% for $d. ", description = "Infligge $s1 danni da fuoco a chi si trova nel raggio dell'esplosione, più altri $443813s1 danni naturali ogni 2 sec per 10 secondi. Riduce inoltre la velocità di movimento dei bersagli colpiti del 25% per $d. " },
    [435977] = { en = "Chance on spell cast to increase your damage and healing by up to $435978s1 for $435978d.", description = "Probabilità all'attivazione di un incantesimo di aumentare i danni e le cure fino a $435978s1 per $435978d." },
    [435982] = { en = "Your attacks have a 5% chance of restoring $435981s1 mana.", description = "I tuoi attacchi hanno una probabilità del 5% di ripristinare $435981s1 mana." },
    [436284] = { en = "Increases the critical hit chance of Holy Shock by $s1%.", description = "Aumenta del $s1% la probabilità di colpo critico di Shock Sacro." },
    [436287] = { en = "Increases the damage of your Wrath spell by up to $s1%.", description = "Aumenta fino al $s1% i danni del tuo incantesimo Ira." },
    [436346] = { en = "A delayed explosion of blood and light occurs around the caster, causing $s1 Twilight damage to all targets within $a1 yards.", description = "Un'esplosione ritardata di sangue e luce si verifica attorno all'incantatore, infliggendo $s1 danni del Crepuscolo a tutti i bersagli entro $a1 metri." },
    [436347] = { en = "Unleash a delayed explosion of blood and light, causing $436346s1 Twilight damage to all targets within $436346a1 yards.", description = "Scatena un'esplosione ritardata di sangue e luce, infliggendo $436346s1 danni del Crepuscolo a tutti i bersagli entro $436346a1 metri." },
    [436364] = { en = "Each time you strike an enemy with a two-handed weapon, you gain $436365s1% attack speed with two-handed weapons, $436365s2% increased Attack Power, and $436365s3% increased chance to hit with spells for $436365d. This effect is lost if you strike an enemy with a one-handed weapon.", description = "Ogni volta che colpisci un nemico con un'arma a due mani, ottieni $436365s1% di velocità d'attacco con le armi a due mani, $436365s2% di Potenza d'attacco e $436365s3% di probabilità di colpire con gli incantesimi per $436365d. Questo effetto svanisce se colpisci un nemico con un'arma a una mano." },
    [436367] = { en = "Gain the Two-Handed Mastery ability:\r\n\r\n$@spellicon436364\r\n$@spelldesc436364", description = "Ottieni l'abilità Maestria a due mani:\r\n\r\n$@spellicon436364\r\n$@spelldesc436364" },
    [436368] = { en = "Engrave your chest or robe with the Two-Handed Mastery rune:\r\n\r\n$@spellicon436364\r\n$@spelldesc436364", description = "Incidi sul petto o sulla veste la runa Maestria a due mani:\r\n\r\n$@spellicon436364\r\n$@spelldesc436364" },
    [436412] = { en = "Empowered by the brave discoverers that preceded you, experience gains increased by $w1%, and gold earned from quests also increases by $w3%.", description = "Forte dell'aiuto dei coraggiosi esploratori che ti hanno preceduto, ottieni il $w1% di esperienza in più e anche l'oro guadagnato dalle missioni aumenta del $w3%." },
    [436413] = { en = "A delayed explosion of blood and nature occurs around the caster, causing $s1 Plague damage to all targets within $a1 yards.", description = "Un'esplosione ritardata di sangue e natura si verifica attorno all'incantatore, infliggendo $s1 danni da Piaga a tutti i bersagli entro $a1 metri." },
    [436414] = { en = "Unleash a delayed explosion of blood and nature, causing $436413s1 Plague damage to all targets within $436413a1 yards.", description = "Scatena un'esplosione ritardata di sangue e natura, infliggendo $436413s1 danni da Piaga a tutti i bersagli entro $436413a1 metri." },
