    [436441] = { en = "Knight", description = "Cavaliere" },
    [436442] = { en = "Stone Guard", description = "Guardia di pietra" },
    [436477] = { en = "Unleash a violent tempest of steel and blood, causing $s1 Shadowstrike damage to all enemies within $a1 yards.", description = "Scatena una violenta tempesta d'acciaio e sangue, infliggendo $s1 danni da Colpo d'ombra a tutti i nemici entro $a1 metri." },
    [436478] = { en = "Unleash a delayed explosion of blood and fire, causing $436479s1 Shadowflame damage to all targets within $436479a1 yards.", description = "Scatena un'esplosione ritardata di sangue e fuoco, infliggendo $436479s1 danni da Fiamma d'ombra a tutti i bersagli entro $436479a1 metri." },
    [436479] = { en = "A delayed explosion of blood and fire occurs around the caster, causing $s1 Shadowflame damage to all targets within $a1 yards.", description = "Un'esplosione ritardata di sangue e fuoco si verifica attorno all'incantatore, infliggendo $s1 danni da Fiamma d'ombra a tutti i bersagli entro $a1 metri." },
    [436516] = { en = "$?a443369[Heals a friendly target for ${$<healpower>*$436517m1/100} to ${$<healpower>*$436517M1/100}.]\r\n\r\n[Fuses Arcane, Fire, and Frost magic to freeze chronomantic energy into a stored state for later use. You can hold this energy for up to $d before it combusts and expires. When unleashed, heals a friendly target for ${$<healpower>*$436517m1/100} to ${$<healpower>*$436517M1/100}.\r\n\r\nThis spell is considered Arcane, Fire, and Frost for interactions with other spells, talents, and effects.]", description = "$?a443369[Cura un bersaglio amico da ${$<healpower>*$436517m1/100} a ${$<healpower>*$436517M1/100}.]\r\n\r\n[Fonde la magia arcana, del fuoco e del gelo per congelare l'energia cronomantica in uno stato immagazzinato, da usare in seguito. Puoi conservare questa energia per un massimo di $d prima che si consumi e svanisca. Quando viene liberata, cura un bersaglio amico da ${$<healpower>*$436517m1/100} a ${$<healpower>*$436517M1/100}.\r\n\r\nQuesto incantesimo è considerato arcano, del fuoco e del gelo ai fini delle interazioni con altri incantesimi, talenti ed effetti.]" },
    [436517] = { en = "Unleash stored chronomantic energy to instantly heal a friendly target for ${$<healpower>*$m1/100}to ${$<healpower>*$M1/100}.", description = "Libera l'energia cronomantica immagazzinata per curare istantaneamente un bersaglio amico da ${$<healpower>*$m1/100} a ${$<healpower>*$M1/100}." },
    [436608] = { en = "Gain the Fan of Knives ability:\r\n\r\n$@spellicon409240\r\n$@spelldesc409240", description = "Ottieni l'abilità Ventaglio di Lame:\r\n\r\n$@spellicon409240\r\n$@spelldesc409240" },
    [436609] = { en = "Engrave your cloak with the Fan of Knives rune:\r\n\r\n$@spellicon409240\r\n$@spelldesc409240", description = "Incidi sul mantello la runa Ventaglio di coltelli:\r\n\r\n$@spellicon409240\r\n$@spelldesc409240" },
    [436610] = { en = "Gain the Blunderbuss ability:\r\n\r\n$@spellicon436564\r\n$@spelldesc436564", description = "Ottieni l'abilità Archibugio:\r\n\r\n$@spellicon436564\r\n$@spelldesc436564" },
    [436611] = { en = "Gain the Crimson Tempest ability:\r\n\r\n$@spellicon412096\r\n$@spelldesc412096", description = "Ottieni l'abilità Tempesta Cremisi:\r\n\r\n$@spellicon412096\r\n$@spelldesc412096" },
    [436689] = { en = "Increases your pet's critical strike chance by $1%.", description = "Aumenta del $1% la probabilità di colpo critico del tuo famiglio." },
    [437032] = { en = "You gain Soul Harvest for $1242853d if a victim is killed while afflicted with your Drain Soul. Soul Harvest allows your Mana to regenerate at $m1% of normal speed while you are casting spells, and grants a $m2% increase to your Mana regeneration.", description = "Ottieni Raccolto d'anime per $1242853d se una vittima viene uccisa mentre è affetta dal tuo Risucchio d'anima. Raccolto d'anime permette al tuo mana di rigenerarsi al $m1% della velocità normale mentre lanci incantesimi e aumenta la rigenerazione del mana del $m2%." },
    [437059] = { en = "Reduces the mana cost of your Seal spells by $s1.", description = "Riduce il costo in mana dei tuoi incantesimi Sigillo di $s1." },
    [437123] = { en = "A steady shot that causes $s2% ranged weapon damage.", description = "Un tiro costante che infligge il $s2% dei danni dell'arma a distanza." },
    [437324] = { en = "Coming into contact with a slumber cloud makes the target fall asleep for $d, reducing their damage taken and healing received by $s3%.", description = "Entrare in contatto con una nube soporifera fa addormentare il bersaglio per $d, riducendo del $s3% i danni subiti e le cure ricevute." },
    [437327] = { en = "Harness the latent arcane energy in the nearby air to give you charged inspiration, reducing the mana cost of all spells by $M% and increasing damage and healing done by up to $s2 for $d.", description = "Attingi all'energia arcana latente nell'aria circostante per ricevere un'ispirazione carica, riducendo del $M% il costo in mana di tutti gli incantesimi e aumentando fino a $s2 i danni inflitti e le cure effettuate per $d." },
    [437340] = { en = "Engage the radiation mitigation protocols in this helmet, causing you to immediately remove all active poison effects and gain immunity to all Nature damage for $d.", description = "Attiva i protocolli di mitigazione delle radiazioni di questo elmo, rimuovendo immediatamente tutti gli effetti di veleno attivi e conferendoti l'immunità a tutti i danni naturali per $d." },
    [437349] = { en = "Inflicts gneuro-logical shock, instantly dealing $s3 damage to yourself but also increasing your melee and ranged attack speed by $s1% for $d. ", description = "Infligge una scarica gneuro-logica, causandoti istantaneamente $s3 danni, ma aumentando anche del $s1% la velocità d'attacco in mischia e a distanza per $d. " },
    [437353] = { en = "The caster breathes a wave of corrosive magic at the target, inflicting $s1 Nature damage and reducing their armor by $s2% for $d.", description = "L'incantatore soffia un'ondata di magia corrosiva sul bersaglio, infliggendo $s1 danni naturali e riducendone l'armatura del $s2% per $d." },
    [437357] = { en = "Gain gneuromantic meditation, allowing $s% of your mana regeneration to continue while casting and increasing damage and healing done by spells by up to $s2 for $d. ", description = "Ottieni meditazione gneuromantica, che permette al $s% della tua rigenerazione del mana di proseguire mentre lanci incantesimi e aumenta fino a $s2 i danni inflitti e le cure effettuate dagli incantesimi per $d. " },
    [437362] = { en = "Inflicts hyperconductive shock, instantly dealing $s2 damage to yourself but also increasing your spell casting speed by $s% for $d. ", description = "Infligge una scarica iperconduttiva, causandoti istantaneamente $s2 danni, ma aumentando anche del $s% la velocità di lancio degli incantesimi per $d. " },
    [437367] = { en = "On a successful block the whirling razor-sharp gears on this shield inflict $s physical damage to the attacker and $437388s1 physical damage to the bearer.", description = "Quando blocca un attacco, gli ingranaggi affilati e rotanti di questo scudo infliggono $s danni fisici all'attaccante e $437388s1 danni fisici a chi lo impugna." },
    [437368] = { en = "Pull a hyperconductive coin from your belt and flip it. Heads: gain $437698s1% increased critical strike chance with all spells and attacks for $437698d. Tails: gain $437699s1% movement speed for $437699d.", description = "Estrai dalla cintura una moneta iperconduttiva e lanciala. Testa: ottieni il $437698s1% di probabilità di colpo critico in più con tutti gli incantesimi e gli attacchi per $437698d. Croce: ottieni il $437699s1% di velocità di movimento in più per $437699d." },
    [437377] = { en = "Gain intense concentration, reducing movement speed by $s%, but also increasing your spell resistance to all schools by 50, and increasing melee attack speed by $s% for $d. ", description = "Ottieni concentrazione intensa, che riduce la velocità di movimento del $s%, ma aumenta di 50 la tua resistenza a tutte le scuole di magia e del $s% la velocità d'attacco in mischia per $d. " },
    [437382] = { en = "Gain reinforced willpower, preventing Silence, Interrupt effects, and spell pushback for $d.", description = "Ottieni forza di volontà rinforzata, che previene Silenzio, effetti di interruzione e contraccolpi degli incantesimi per $d." },
    [437398] = { en = "The caster shatters the mind of all waking players, inflicting $s1 Shadow damage to them.", description = "L'incantatore frantuma la mente di tutti i giocatori svegli, infliggendo loro $s1 danni da ombra." },
    [437410] = { en = "The caster goes into a deep sleep for $d, reducing damage taken by $s1%.", description = "L'incantatore cade in un sonno profondo per $d, riducendo i danni subiti del $s1%." },
    [437472] = { en = "$@spelldesc437479", description = "$@spelldesc437479" },
    [437474] = { en = "$@spelldesc437479", description = "$@spelldesc437479" },
    [437475] = { en = "$@spelldesc437479", description = "$@spelldesc437479" },
    [437479] = { en = "Balnazzar unleashes a swarm of carrion insects that infest players, causing them to inflict $s1 Shadow damage every $t1 sec to allies within $437480A1 yards for $d. This effect stacks.", description = "Balnazzar scatena uno sciame di insetti necrofagi che infestano i giocatori, facendogli infliggere $s1 danni da ombra ogni $t1 sec agli alleati entro $437480A1 metri per $d. Questo effetto è cumulabile." },
    [437480] = { en = "$@spelldesc437479", description = "$@spelldesc437479" },
    [437503] = { en = "The caster slams the ground, inflicting $s1 Physical damage to players and creating several pillars.", description = "L'incantatore colpisce il terreno, infliggendo $s1 danni fisici ai giocatori e creando diversi pilastri." },
    [437621] = { en = "$@spelldesc437622", description = "$@spelldesc437622" },
    [437622] = { en = "Shades of Balnazzar strike players that aren't within $437627A1 yards of another player, inflicting $437648s1 Shadow damage.", description = "Le Ombre di Balnazzar colpiscono i giocatori che non si trovano entro $437627A1 metri da un altro giocatore, infliggendo $437648s1 danni dell'Ombra." },
    [437627] = { en = "$@spelldesc437622", description = "$@spelldesc437622" },
    [437642] = { en = "$@spelldesc437622", description = "$@spelldesc437622" },
    [437648] = { en = "$@spelldesc437622", description = "$@spelldesc437622" },
    [437650] = { en = "$@spelldesc437622", description = "$@spelldesc437622" },
    [437713] = { en = "Increases all damage done by $s1%", description = "Aumenta tutti i danni inflitti del $s1%." },
    [437739] = { en = "$@spelldesc438170", description = "$@spelldesc438170" },
    [437791] = { en = "The caster gains $s1% of their maximum health every $t1 sec.", description = "L'incantatore rigenera il $s1% della propria salute massima ogni $t1 sec." },
    [437801] = { en = "$@spelldesc437802", description = "$@spelldesc437802" },
    [437813] = { en = "Coming into contact with the light sends the Sreeching Terror into a frenzy, increasing attack and movement speed by $s$%", description = "Il contatto con la luce manda il Terrore Stridente in preda alla frenesia, aumentando la velocità d'attacco e di movimento del $s$%." },
    [437817] = { en = "The caster creates zones of holy energy, inflicting $437837s1 Holy damage every $s1 sec to players within.", description = "L'incantatore crea zone di energia sacra, infliggendo $437837s1 danni sacri ogni $s1 sec. ai giocatori al loro interno." },
    [437833] = { en = "$@spelldesc437933", description = "$@spelldesc437933" },
    [437834] = { en = "$@spelldesc437933", description = "$@spelldesc437933" },
    [437837] = { en = "$@spelldesc437817", description = "$@spelldesc437817" },
    [437840] = { en = "$@spelldesc437846", description = "$@spelldesc437846" },
    [437846] = { en = "The infernal burns with a wicked intensity, inflicting $437840s1 Fire damage to enemies with $A1 yards every $t2 sec, but the light also provides immunity to Suppressive Darkness.", description = "L'infernale arde con un'intensità maligna, infliggendo $437840s1 danni da fuoco ai nemici entro $A1 metri ogni $t2 sec., ma la luce conferisce anche immunità all'Oscurità Oppressiva." },
    [437847] = { en = "Slashes out at a target, inflicting $s1% weapon damage as Shadow and reducing healing received by $s2% for $d.", description = "Colpisce un bersaglio con un fendente, infliggendo danni da ombra pari al $s1% dei danni dell'arma e riducendo le cure ricevute del $s2% per $d." },
    [437868] = { en = "Causes dark magic to flow around targets, inflicting $s1 Shadow damage every $t1 sec and reducing damage done by $s2% for $d.", description = "Fa fluire la magia oscura attorno ai bersagli, infliggendo $s1 danni da ombra ogni $t1 sec. e riducendo i danni inflitti del $s2% per $d." },
    [437884] = { en = "The caster consecrates the ground for $d, inflicting $437887s1 Holy damage every $s1 sec to players within.", description = "L'incantatore consacra il terreno per $d, infliggendo $437887s1 danni sacri ogni $s1 sec. ai giocatori al suo interno." },
    [437887] = { en = "$@spelldesc437884", description = "$@spelldesc437884" },
    [437891] = { en = "Strikes the target, inflicting $s1% weapon damage as Holy and increasing Holy damage taken by $s2% for $d.", description = "Colpisce il bersaglio, infliggendo danni sacri pari al $s1% dei danni dell'arma e aumentando i danni sacri subiti del $s2% per $d." },
    [437902] = { en = "$@spelldesc437933", description = "$@spelldesc437933" },
    [437920] = { en = "Pulls all players towards the caster, inflicting $s1 Holy damage to them.", description = "Attira tutti i giocatori verso l'incantatore, infliggendo loro $s1 danni sacri." },
    [437922] = { en = "$@spelldesc437846", description = "$@spelldesc437846" },
    [437927] = { en = "Causes dark magic to flow around targets, inflicting $s1 Shadow damage every $t1 sec.", description = "Fa fluire la magia oscura attorno ai bersagli, infliggendo $s1 danni da ombra ogni $t1 sec." },
    [437928] = { en = "Releases a scream, sending enemies fleeing in fear for $d.", description = "Lancia un urlo, facendo fuggire i nemici terrorizzati per $d." },
    [437930] = { en = "Shields the caster for $d, absorbing up to $s1 damage.", description = "Protegge l'incantatore per $d, assorbendo fino a $s1 danni." },
    [437983] = { en = "Balnazzar marks players for domination. After $D players afflicted and allies within $437987A1 to become charmed for $437987D.", description = "Balnazzar marchia i giocatori per sottometterli. Dopo $D, i giocatori colpiti e gli alleati entro $437987A1 diventano soggiogati per $437987D." },
    [437984] = { en = "$@spellname437983", description = "$@spellname437983" },
    [437987] = { en = "$@spellname437983\r\n", description = "$@spellname437983\r\n" },
    [437997] = { en = "When your pet scores a critical hit with a special ability, you instantly regenerate $437999s1% of your maximum mana. This cannot occur more often than once every 2 sec.", description = "Quando il tuo famiglio mette a segno un colpo critico con un'abilità speciale, rigeneri istantaneamente il $437999s1% del mana massimo. Questo effetto può attivarsi al massimo una volta ogni 2 sec." },
    [438040] = { en = "Removes all your existing combo points from your target and stores them for up to $d. These stored combat points will be transferred to the next non-player enemy you hit with a melee or ranged ability.\r\n", description = "Rimuove tutti i punti combo attuali dal bersaglio e li conserva per un massimo di $d. Questi punti combo conservati verranno trasferiti al prossimo nemico non giocatore che colpirai con un'abilità da mischia o a distanza.\r\n" },
    [438101] = { en = "Devours nearby players, inflicting $s1 Nature damage. This also reduces damage done by $s3% and movement speed by $s5% for $d.", description = "Divora i giocatori vicini, infliggendo $s1 danni naturali. Inoltre, riduce i danni inflitti del $s3% e la velocità di movimento del $s5% per $d." },
    [438136] = { en = "$@spelldesc438130", description = "$@spelldesc438130" },
    [438142] = { en = "The caster gets gunk all over targets, inflicting $s1 Nature damage every $t1 sec and reducing their movement speed by $s2% for $d.", description = "L'incantatore ricopre i bersagli di melma, infliggendo $s1 danni naturali ogni $t1 sec. e riducendone la velocità di movimento del $s2% per $d." },
    [438536] = { en = "Increases critical strike chance of spells by $s1%, grants $s2 spell damage and healing, and increases melee and ranged attack speed by $s4%. 120 minute duration.", description = "Aumenta la probabilità di critico degli incantesimi del $s1%, conferisce $s2 danni magici e cure e aumenta la velocità d'attacco in mischia e a distanza del $s4%. Dura 120 minuti." },
    [438537] = { en = "Increases critical strike chance of spells by $s1%, grants $s2 spell damage and healing, and increases melee and ranged attack speed by $s4%. 120 minute duration.\r\n", description = "Aumenta la probabilità di critico degli incantesimi del $s1%, conferisce $s2 danni magici e cure e aumenta la velocità d'attacco in mischia e a distanza del $s4%. Dura 120 minuti.\r\n" },
    [439431] = { en = "Imbue the Shaman's weapon with wind.  Each hit has a 20% chance of granting you $8233s2 extra $lattack:attacks; with $8233s1 extra melee attack power.  Lasts for 5 minutes.", description = "Infondi l'arma dello Sciamano con il vento. Ogni colpo ha una probabilità del 20% di fornirti $8233s2 $lattacco:attacchi; aggiuntivi, con $8233s1 potere d'attacco in mischia aggiuntivo. Dura 5 minuti." },
    [439462] = { en = "Coats a weapon with poison that lasts for 30 minutes.\r\nEach strike has a $h% chance of poisoning the enemy, reducing the enemy's armor by $439471s1 for $439471d.\r\n\r\nSebacious Poison benefits from the Improved Expose Armor talent.", description = "Ricopre un'arma di veleno che dura 30 minuti.\r\nOgni colpo ha una probabilità del $h% di avvelenare il nemico, riducendone l'armatura di $439471s1 per $439471d.\r\n\r\nIl Veleno sebaceo beneficia del talento Esponi Armatura Migliorato." },
    [439464] = { en = "Coats a weapon with poison that lasts for 30 minutes.\r\nEach strike has a $h% chance of poisoning the enemy, increasing the time between the enemy's melee attacks by $439472s1% for $439472d.", description = "Ricopre un'arma di veleno che dura 30 minuti.\r\nOgni colpo ha una probabilità del $h% di avvelenare il nemico, aumentando l'intervallo tra i suoi attacchi in mischia del $439472s1% per $439472d." },
    [439465] = { en = "Coats a weapon with poison that lasts for 30 minutes.\r\nEach strike has a $h% chance of poisoning the enemy, reducing the enemy's melee attack power by $439473s1 for $439473d.", description = "Ricopre un'arma di veleno che dura 30 minuti.\r\nOgni colpo ha una probabilità del $h% di avvelenare il nemico, riducendone il potere d'attacco in mischia di $439473s1 per $439473d." },
    [439500] = { en = "Coats a weapon with poison that lasts for 30 minutes.\r\nEach strike has a $439462h% chance of poisoning the enemy, reducing the enemy's armor by $439471s1 for $439471d.  105 charges.\r\n\r\nSebacious Poison benefits from the Improved Expose Armor talent.", description = "Ricopre un'arma di veleno che dura 30 minuti.\r\nOgni colpo ha una probabilità del $439462h% di avvelenare il nemico, riducendone l'armatura di $439471s1 per $439471d. 105 cariche.\r\n\r\nIl Veleno sebaceo beneficia del talento Esponi Armatura Migliorato." },
    [439503] = { en = "Coats a weapon with poison that lasts for 30 minutes.\r\nEach strike has a $439465h% chance of poisoning the enemy, reducing the enemy's melee attack power by $439473s1 for $439473d.  105 charges.", description = "Ricopre un'arma di veleno che dura 30 minuti.\r\nOgni colpo ha una probabilità del $439465h% di avvelenare il nemico, riducendone il potere d'attacco in mischia di $439473s1 per $439473d. 105 cariche." },
    [439505] = { en = "Coats a weapon with poison that lasts for 30 minutes.\r\nEach strike has a $439464h% chance of poisoning the enemy, increasing the time between the enemy's melee attacks by $439472s1% for $439472d.  105 charges.", description = "Ricopre un'arma di veleno che dura 30 minuti.\r\nOgni colpo ha una probabilità del $439464h% di avvelenare il nemico, aumentando l'intervallo tra i suoi attacchi in mischia del $439472s1% per $439472d. 105 cariche." },
    [439510] = { en = "While in Cat Form, your Swipe ability becomes Swipe (Cat), and while in Bear Form, your Swipe ability strikes up to $s1 additional enemies.\r\n\r\nSwipe (Cat)\r\n$@spellicon411128\r\n$@spelldesc411128", description = "In Forma Felina, la tua abilità Spazzata diventa Spazzata (Felina); in Forma d'Orso, la tua abilità Spazzata colpisce fino a $s1 nemici aggiuntivi.\r\n\r\nSpazzata (Felina)\r\n$@spellicon411128\r\n$@spelldesc411128" },
    [439733] = { en = "Shapeshift into the Tree of Life. While in this form you increase healing received by $439745s1% for all party members within $439745a1 yards, Wild Growth healing is increased by $439734s8%, your heal over time spells cost $439734s1% less, you gain $439734s2% increased Spirit, you gain $439734s3% increased armor, and you cannot cast harmful spells.\r\n\r\nThe act of shapeshifting frees the caster of Polymorph and Movement Impairing effects.", description = "Ti trasforma nell'Albero della Vita. In questa forma, aumenti del $439745s1% le cure ricevute da tutti i membri del gruppo entro $439745a1 metri, aumenti del $439734s8% le cure di Crescita Rigogliosa, riduci del $439734s1% il costo degli incantesimi di cura periodica, aumenti dello $439734s2% lo Spirito e aumenti del $439734s3% l'armatura; inoltre, non puoi lanciare incantesimi nocivi.\r\n\r\nLa trasformazione libera l'incantatore dagli effetti di Polimorfia e dagli effetti che limitano il movimento." },
    [439745] = { en = "Increased all healing received by party members within $a1 yards by $s1%.", description = "Aumenta del $s1% tutte le cure ricevute dai membri del gruppo entro $a1 metri." },
    [439748] = { en = "You summon a flurry of stars from the sky over $d, striking targets within $439755a yards of your location, each dealing ${$439753m1*$<damagepower>/100} to ${$439753M1*$<damagepower>/100} Arcane damage to its target and ${$439756m1*$<damagepower>/100} Arcane damage to all other enemies within $439756a1 yards. Maximum 20 stars.\r\n\r\nShapeshifting or mounting cancels the effect. Any effect which causes you to lose control of your character will suppress the Starfall effect.\r\n\r\nBenefits from and triggers most talents and effects that trigger or benefit from Moonfire.", description = "Evoca una pioggia di stelle dal cielo per $d, che colpisce i bersagli entro $439755a metri dalla tua posizione. Ogni stella infligge da ${$439753m1*$<damagepower>/100} a ${$439753M1*$<damagepower>/100} danni arcani al bersaglio e ${$439756m1*$<damagepower>/100} danni arcani a tutti gli altri nemici entro $439756a1 metri. Massimo 20 stelle.\r\n\r\nLa trasformazione o la cavalcatura annulla l'effetto. Qualsiasi effetto che ti fa perdere il controllo del personaggio sopprime l'effetto di Pioggia di Stelle.\r\n\r\nBeneficia della maggior parte dei talenti e degli effetti che si attivano con Fuoco Lunare o ne potenziano gli effetti, e li attiva." },
    [439753] = { en = "You summon a flurry of stars from the sky on all targets within 30 yards of the caster, each dealing $50288s1 Arcane damage. Also causes $50294s1 Arcane damage to all other enemies within $50294a1 yards of the enemy target. Maximum 20 stars. Lasts $48505d.", description = "Evoca una pioggia di stelle dal cielo su tutti i bersagli entro 30 metri dall'incantatore; ogni stella infligge $50288s1 danni arcani. Infligge inoltre $50294s1 danni arcani a tutti gli altri nemici entro $50294a1 metri dal bersaglio nemico. Massimo 20 stelle. Dura $48505d." },
    [439765] = { en = "Engrave your cloak with the Improved Swipe rune:\r\n\r\n$@spellicon439510\r\n$@spelldesc439510", description = "Incidi la tua cappa con la runa Spazzata Migliorata:\r\n\r\n$@spellicon439510\r\n$@spelldesc439510" },
    [439766] = { en = "Gain the Tree of Life ability:\r\n\r\n$@spellicon439766\r\n$@spelldesc439733", description = "Ottieni l'abilità Albero della Vita:\r\n\r\n$@spellicon439766\r\n$@spelldesc439733" },
    [439767] = { en = "Engrave your cloak with the Tree of Life rune:\r\n\r\n$@spellicon439766\r\n$@spelldesc439733", description = "Incidi la tua cappa con la runa Albero della Vita:\r\n\r\n$@spellicon439766\r\n$@spelldesc439733" },
    [439768] = { en = "Gain the Starfall\r\n ability:\r\n\r\n$@spellicon439748\r\n$@spelldesc439748", description = "Ottieni l'abilità Pioggia di Stelle\r\n:\r\n\r\n$@spellicon439748\r\n$@spelldesc439748" },
    [439770] = { en = "Engrave your cloak with the Starfall\r\n rune:\r\n\r\n$@spellicon439748\r\n$@spelldesc439748", description = "Incidi la tua cappa con la runa Pioggia di Stelle\r\n:\r\n\r\n$@spellicon439748\r\n$@spelldesc439748" },
    [440113] = { en = "Your melee hits have a $h% chance to grant Sudden Death. Sudden Death allows one use of Execute regardless of the target's health state. When Execute is enabled by Sudden Death, you will retain $s2 rage after using Execute.", description = "I tuoi attacchi in mischia hanno una probabilità del $h% di attivare Morte Improvvisa. Morte Improvvisa consente di usare Esecuzione una volta, indipendentemente dalla salute del bersaglio. Quando Morte Improvvisa attiva Esecuzione, dopo averla usata conserverai $s2 ira." },
    [440484] = { en = "Damaging a target with Bloodthirst, Mortal Strike, or Shield Slam has a 100% chance the first time and a $s2% chance each subsequent time to Enrage you (activating abilities which requiring being Enraged), and cause you to deal $440483s1% increased Physical damage for $440483d.", description = "Infliggere danni a un bersaglio con Sete di Sangue, Colpo Mortale o Impatto con lo Scudo ha una probabilità del 100% la prima volta e del $s2% a ogni utilizzo successivo di farti Infuriare (attivando le abilità che richiedono di essere Infuriati) e di aumentare del $440483s1% i danni fisici che infliggi per $440483d." },
    [440492] = { en = "Engrave your cloak with the Fresh Meat\r\n rune:\r\n\r\n$@spellicon440484\r\n$@spelldesc440484", description = "Incidi il tuo mantello con la runa Carne Fresca\r\n:\r\n\r\n$@spellicon440484\r\n$@spelldesc440484" },
    [440493] = { en = "Gain the Fresh Meat ability:\r\n\r\n$@spellicon440484\r\n$@spelldesc440484", description = "Ottieni l'abilità Carne Fresca:\r\n\r\n$@spellicon440484\r\n$@spelldesc440484" },
    [440494] = { en = "Engrave your cloak with the Sudden Death rune:\r\n\r\n$@spellicon440113\r\n$@spelldesc440113", description = "Incidi il tuo mantello con la runa Morte Improvvisa:\r\n\r\n$@spellicon440113\r\n$@spelldesc440113" },
    [440495] = { en = "Gain the Fresh Meat ability:\r\n\r\n$@spellicon440113\r\n$@spelldesc440113", description = "Ottieni l'abilità Carne Fresca:\r\n\r\n$@spellicon440113\r\n$@spelldesc440113" },
    [440496] = { en = "Engrave your cloak with the Shockwave\r\n rune:\r\n\r\n$@spellicon440488\r\n$@spelldesc440488", description = "Incidi il tuo mantello con la runa Onda d'Urto\r\n:\r\n\r\n$@spellicon440488\r\n$@spelldesc440488" },
    [440497] = { en = "Gain the Shockwave ability:\r\n\r\n$@spellicon440488\r\n$@spelldesc440488", description = "Ottieni l'abilità Onda d'Urto:\r\n\r\n$@spellicon440488\r\n$@spelldesc440488" },
    [440520] = { en = "Reduces the mana cost of your Volley by $s1%, reduces its cooldown by $s2%, increases its damage by $s5%, and it no longer suffers pushback from damaging attacks. Volley also deals $s4% of your ranged Attack Power as additional damage each time it deals damage.", description = "Riduce del $s1% il costo in mana della tua Salva, ne riduce del $s2% il tempo di recupero e ne aumenta del $s5% i danni. Inoltre, i colpi che infliggono danni non ne ritardano più il lancio. Salva infligge anche danni aggiuntivi pari al $s4% della tua potenza d'attacco a distanza ogni volta che infligge danni." },
    [440529] = { en = "Reduces the mana cost of your Trap abilities and melee abilities by $s1%. In addition, your critical strikes have a $m3% chance to allow $1242688s1% of your Mana regeneration to continue while casting for $1242688d.", description = "Riduce del $s1% il costo in mana delle tue abilità Trappola e delle tue abilità da mischia. Inoltre, i tuoi colpi critici hanno una probabilità del $m3% di permettere a $1242688s1% della tua rigenerazione del mana di proseguire durante il lancio degli incantesimi per $1242688d." },
    [440533] = { en = "You gain $440531s1% movement speed for $440531d after using Raptor Strike.\r\n\r\nYour pet's damaging abilities send the target into a Rabid Frenzy, increasing their melee attack power by $s2 but reducing armor by $s3 for $1218358d.  Rabid enemies will not flee and will ignore Fear and Horror effects.", description = "Dopo aver usato Colpo del Raptor, ottieni $440531s1% di velocità di movimento per $440531d.\r\n\r\nLe abilità del tuo famiglio che infliggono danni fanno entrare il bersaglio in una Frenesia Rabbiosa, aumentando la sua potenza d'attacco in mischia di $s2 ma riducendone l'armatura di $s3 per $1218358d. I nemici in Frenesia Rabbiosa non fuggono e ignorano gli effetti di Paura e Orrore." },
    [440557] = { en = "Engrave your cloak with the Resourcefulness rune:\r\n\r\n$@spellicon440529\r\n$@spelldesc440529", description = "Incidi il tuo mantello con la runa Intraprendenza:\r\n\r\n$@spellicon440529\r\n$@spelldesc440529" },
    [440558] = { en = "Gain the Resourcefulness ability:\r\n\r\n$@spellicon440529\r\n$@spelldesc440529", description = "Ottieni l'abilità Intraprendenza:\r\n\r\n$@spellicon440529\r\n$@spelldesc440529" },
    [440560] = { en = "Engrave your cloak with the Improved Volley rune:\r\n\r\n$@spellicon440520\r\n$@spelldesc440520", description = "Incidi il tuo mantello con la runa Salva Migliorata:\r\n\r\n$@spellicon440520\r\n$@spelldesc440520" },
    [440561] = { en = "Gain the Improved Volley ability:\r\n\r\n$@spellicon440520\r\n$@spelldesc440520", description = "Ottieni l'abilità Salva Migliorata:\r\n\r\n$@spellicon440520\r\n$@spelldesc440520" },
    [440563] = { en = "Engrave your cloak with the Hit and Run rune:\r\n\r\n$@spellicon440533\r\n$@spelldesc440533", description = "Incidi il tuo mantello con la runa Mordi e Fuggi:\r\n\r\n$@spellicon440533\r\n$@spelldesc440533" },
    [440564] = { en = "Gain the Hit and Run ability:\r\n\r\n$@spellicon440533\r\n$@spelldesc440533", description = "Ottieni l'abilità Mordi e Fuggi:\r\n\r\n$@spellicon440533\r\n$@spelldesc440533" },
    [440569] = { en = "Reduces the cooldown of your Chain Lightning by $s1%, causes your Earthbind Totem to root targets for $440574d when cast, and increases the periodic damage done by your Flame Shock by $s3%.", description = "Riduce del $s1% il tempo di recupero della tua Catena di Fulmini, fa sì che il tuo Totem del Vincolo Terrestre immobilizzi i bersagli per $440574d quando viene evocato e aumenta del $s3% i danni periodici inflitti dalla tua Folgore di Fuoco." },
    [440591] = { en = "Removes all movement impairing effects and increases the movement speed of you and your Spirit Wolves by $s1% for $d.", description = "Rimuove tutti gli effetti che limitano il movimento e aumenta del $s1% la velocità di movimento tua e dei tuoi Lupi Spirituali per $d." },
    [440593] = { en = "Spirit Wolves' attacks heal them and their master for $s1% of damage done", description = "Gli attacchi dei Lupi Spirituali curano loro e il loro padrone per un ammontare pari al $s1% dei danni inflitti" },
    [440630] = { en = "Engrave your cloak with the Feral Spirit rune:\r\n\r\n$@spellicon440580\r\n$@spelldesc440580", description = "Incidi il tuo mantello con la runa Spirito Ferino:\r\n\r\n$@spellicon440580\r\n$@spelldesc440580" },
    [440631] = { en = "Gain the Feral Spirit ability:\r\n\r\n$@spellicon440580\r\n$@spelldesc440580", description = "Ottieni l'abilità Spirito Ferino:\r\n\r\n$@spellicon440580\r\n$@spelldesc440580" },
    [440633] = { en = "Gain the Storm, Earth, and Fire ability:\r\n\r\n$@spellicon440569\r\n$@spelldesc440569", description = "Ottieni l'abilità Tempesta, Terra e Fuoco:\r\n\r\n$@spellicon440569\r\n$@spelldesc440569" },
    [440634] = { en = "Engrave your cloak with the Storm, Earth, and Fire rune:\r\n\r\n$@spellicon440569\r\n$@spelldesc440569", description = "Incidi il tuo mantello con la runa Tempesta, Terra e Fuoco:\r\n\r\n$@spellicon440569\r\n$@spelldesc440569" },
    [440658] = { en = "Slam the target with your shield, causing Holy damage based on your block value plus an additional ${$m1*$<damagepower>/100}.", description = "Colpisce il bersaglio con lo scudo, infliggendo danni sacri in base al valore di blocco più un ammontare aggiuntivo pari a ${$m1*$<damagepower>/100}." },
    [440666] = { en = "When your Vindication talent is triggered, it also decreases the target's Attack Power by ${$440667m1/-3} per talent point and increases your Strength, Agility, and Attack Power by ${$440668m1/3}% per talent point. Vindication duration increased to $s1 sec.", description = "Quando si attiva il tuo talento Giustificazione, riduce anche la potenza d'attacco del bersaglio di ${$440667m1/-3} per punto talento e aumenta la tua Forza, Agilità e potenza d'attacco di ${$440668m1/3}% per punto talento. La durata di Giustificazione aumenta a $s1 sec." },
    [440672] = { en = "When your Judgement or Crusader Strike deals a critical strike, your target will take $s1% additional damage over $61840d.", description = "Quando il tuo Giudizio o Colpo del Crociato infligge un colpo critico, il bersaglio subisce il $s1% di danni aggiuntivi per $61840d." },
    [440788] = { en = "Engrave your cloak with the Shield of Righteousness rune:\r\n\r\n$@spellicon440658\r\n$@spelldesc440658", description = "Incidi il tuo mantello con la runa Scudo della Rettitudine:\r\n\r\n$@spellicon440658\r\n$@spelldesc440658" },
    [440789] = { en = "Gain the Shield of Righteousness ability:\r\n\r\n$@spellicon440658\r\n$@spelldesc440658", description = "Ottieni l'abilità Scudo della Rettitudine:\r\n\r\n$@spellicon440658\r\n$@spelldesc440658" },
    [440790] = { en = "Engrave your cloak with the Shock and Awe rune:\r\n\r\n$@spellicon462834\r\n$@spelldesc462834", description = "Incidi il tuo mantello con la runa Scossa e Stupore:\r\n\r\n$@spellicon462834\r\n$@spelldesc462834" },
    [440791] = { en = "Gain the Shock and Awe ability:\r\n\r\n$@spellicon462834\r\n$@spelldesc462834", description = "Ottieni l'abilità Scossa e Stupore:\r\n\r\n$@spellicon462834\r\n$@spelldesc462834" },
    [440792] = { en = "Engrave your cloak with the Righteous Vengeance rune:\r\n\r\n$@spellicon440672\r\n$@spelldesc440672", description = "Incidi il tuo mantello con la runa Vendetta Virtuosa:\r\n\r\n$@spellicon440672\r\n$@spelldesc440672" },
    [440794] = { en = "Gain the Righteous Vengeance ability:\r\n\r\n$@spellicon440672\r\n$@spelldesc440672", description = "Ottieni l'abilità Vendetta Virtuosa:\r\n\r\n$@spellicon440672\r\n$@spelldesc440672" },
    [440802] = { en = "Launches an orb of swirling ice which rapidly moves forward over $d. While it is moving, every $440804t sec the orb deals ${$440809m2*$<power>/100*$<frostdamage>} Frost Damage and applies a Chill for $440809s1% movement speed reduction to all enemies it passes through. The first time it damages an enemy, its movement will slow and it will have a 100% chance to trigger the Fingers of Frost rune.", description = "Scaglia una sfera di ghiaccio turbinante che avanza rapidamente per $d. Durante il movimento, ogni $440804t sec la sfera infligge ${$440809m2*$<power>/100*$<frostdamage>} danni da gelo e applica un Rallentamento che riduce la velocità di movimento del $440809s1% a tutti i nemici che attraversa. La prima volta che danneggia un nemico, rallenta il proprio movimento e ha una probabilità del 100% di attivare la runa Dita di Ghiaccio." },
    [440858] = { en = "Engrave your cloak with the Frozen Orb\r\nrune:\r\n\r\n$@spellicon440802\r\n$@spelldesc440802", description = "Incidi il tuo mantello con la runa Globo Congelato\r\n:\r\n\r\n$@spellicon440802\r\n$@spelldesc440802" },
    [440859] = { en = "Gain the Frozen Orb ability:\r\n\r\n$@spellicon440802\r\n$@spelldesc440802", description = "Ottieni l'abilità Globo Congelato:\r\n\r\n$@spellicon440802\r\n$@spelldesc440802" },
    [440870] = { en = "Reduces the cooldown of your Soul Fire spell by $m2%. When you cast Shadow Bolt or Searing Pain on an enemy below $m3% health, they deal $m4% increased damage, and for the next $440873d your Soul Fire spell has its cast time reduced by $m1% and costs no Soul Shards.", description = "Riduce del $m2% il tempo di recupero dell'incantesimo Fuoco dell'Anima. Quando lanci Dardo d'Ombra o Dolore Bruciante su un nemico con meno del $m3% della salute, questi infliggono il $m4% di danni aggiuntivi; inoltre, per i successivi $440873d il tempo di lancio dell'incantesimo Fuoco dell'Anima è ridotto del $m1% e non consuma Frammenti d'Anima." },
    [440882] = { en = "Your spirit becomes infused with demonic energy, reducing all Magic damage you take by a percentage equal to $s2% of your Physical damage reduction from armor. Lasts $d.", description = "Il tuo spirito si infonde di energia demoniaca, riducendo tutti i danni magici subiti di una percentuale pari al $s2% della riduzione dei danni fisici fornita dalla tua armatura. Dura $d." },
    [440922] = { en = "Engrave your boots with the Decimation rune:\r\n\r\n$@spellicon440870\r\n$@spelldesc440870", description = "Incidi i tuoi stivali con la runa Decimazione:\r\n\r\n$@spellicon440870\r\n$@spelldesc440870" },
    [440923] = { en = "Gain the Decimation ability:\r\n\r\n$@spellicon440870\r\n$@spelldesc440870", description = "Ottieni l'abilità Decimazione:\r\n\r\n$@spellicon440870\r\n$@spelldesc440870" },
    [440924] = { en = "Engrave your cloak with the Mark of Chaos rune:\r\n\r\n$@spellicon440892\r\n$@spelldesc440892", description = "Incidi il tuo mantello con la runa Marchio del Caos:\r\n\r\n$@spellicon440892\r\n$@spelldesc440892" },
    [440925] = { en = "Gain the Mark of Chaos ability:\r\n\r\n$@spellicon440892\r\n$@spelldesc440892", description = "Ottieni l'abilità Marchio del Caos:\r\n\r\n$@spellicon440892\r\n$@spelldesc440892" },
    [440926] = { en = "Engrave your cloak with the Infernal Armor rune:\r\n\r\n$@spellicon440882\r\n$@spelldesc440882", description = "Incidi il tuo mantello con la runa Armatura Infernale:\r\n\r\n$@spellicon440882\r\n$@spelldesc440882" },
    [440927] = { en = "Gain the Infernal Armor ability:\r\n\r\n$@spellicon440882\r\n$@spelldesc440882", description = "Ottieni l'abilità Armatura Infernale:\r\n\r\n$@spellicon440882\r\n$@spelldesc440882" },
    [442211] = { en = "When activated, this ability causes your Mangle (Bear) ability to hit up to $s3 targets and have no cooldown, and reduces the energy cost of all your Cat Form abilities by $s1%.  Lasts $d. Requires Bear Form, Cat Form, or Dire Bear Form to activate.\r\n\r\nClears the effect of Fear and makes you immune to Fear for the duration.\r\n", description = "Quando viene attivata, questa abilità fa sì che la tua abilità Dilaniamento (Orso) colpisca fino a $s3 bersagli e non abbia tempo di recupero, e riduce del $s1% il costo in energia di tutte le tue abilità in Forma di Felino. Dura $d. Richiede la Forma di Orso, la Forma di Felino o la Forma di Orso Feroce per essere attivata.\r\n\r\nDissolve l'effetto di Paura e ti rende immune a Paura per tutta la durata.\r\n" },
    [442222] = { en = "Electrocutioner 6000 unleashes a blast of lightning at the furthest target, inflicting $s1 Nature damage and leaping up to $x times.  Each player hit by this effect takes $s2% increased damage from $@spellname433251 for $d.", description = "Electrocutioner 6000 scatena una scarica di fulmini contro il bersaglio più lontano, infliggendo $s1 danni da natura e balzando fino a $x volte. Ogni giocatore colpito da questo effetto subisce il $s2% di danni in più da $@spellname433251 per $d." },
    [442223] = { en = "Electrocutioner 6000 unleashes a blast of lightning at the furthest target, inflicting $s1 Nature damage and leaping up to $x times.  Each player hit by this effect takes $s2% increased damage from $@spellname433251 for $d.", description = "Electrocutioner 6000 scatena una scarica di fulmini contro il bersaglio più lontano, infliggendo $s1 danni da natura e balzando fino a $x volte. Ogni giocatore colpito da questo effetto subisce il $s2% di danni in più da $@spellname433251 per $d." },
    [442225] = { en = "Electrocutioner 6000 unleashes a blast of lightning at the furthest target, inflicting $s1 Nature damage and leaping up to $x times.  Each player hit by this effect takes $s2% increased damage from $@spellname433251 for $d.", description = "Electrocutioner 6000 scatena una scarica di fulmini contro il bersaglio più lontano, infliggendo $s1 danni da natura e balzando fino a $x volte. Ogni giocatore colpito da questo effetto subisce il $s2% di danni in più da $@spellname433251 per $d." },
    [442813] = { en = "Skill with Swords and Two-Handed Swords increased by $s1. This effect is not cumulative with racial bonuses or other ring runes.", description = "Abilità con Spade e Spade a Due Mani aumentata di $s1. Questo effetto non è cumulabile con bonus razziali o altre rune degli anelli." },
    [442876] = { en = "Skill with Axes and Two-Handed Axes increased by $s1. This effect is not cumulative with racial bonuses or other ring runes.", description = "Abilità con Asce e Asce a Due Mani aumentata di $s1. Questo effetto non è cumulabile con bonus razziali o altre rune degli anelli." },
    [442881] = { en = "Skill with Maces and Two-Handed Maces increased by $s1. This effect is not cumulative with racial bonuses or other ring runes.", description = "Abilità con Mazze e Mazze a Due Mani aumentata di $s1. Questo effetto non è cumulabile con bonus razziali o altre rune degli anelli." },
    [442887] = { en = "Skill with Daggers increased by $s1. This effect is not cumulative with racial bonuses or other ring runes.", description = "Abilità con Pugnali aumentata di $s1. Questo effetto non è cumulabile con bonus razziali o altre rune degli anelli." },
    [442890] = { en = "Skill with Fist Weapons (Unarmed) increased by $s1. This effect is not cumulative with racial bonuses or other ring runes.", description = "Abilità con Armi a Pugno (Senz'Armi) aumentata di $s1. Questo effetto non è cumulabile con bonus razziali o altre rune degli anelli." },
    [442891] = { en = "Skill with Bows, Guns, Crossbows, and Thrown weapons increased by $s1.  This effect is not cumulative with racial bonuses or other ring runes.", description = "Abilità con Archi, Armi da Fuoco, Balestre e Armi da Lancio aumentata di $s1. Questo effetto non è cumulabile con bonus razziali o altre rune degli anelli." },
    [442892] = { en = "Skill with Staves and Polearms increased by $s1. This effect is not cumulative with racial bonuses or other ring runes.", description = "Abilità con Bastoni e Armi inastate aumentata di $s1. Questo effetto non è cumulabile con i bonus razziali o altre rune per anelli." },
    [442901] = { en = "Chance to hit with melee attacks increased by $s2% and chance for enemies to dodge your melee attacks reduced by $s1% while in Bear Form, Cat Form, or Dire Bear Form. Not cumulative with other ring runes.", description = "Probabilità di colpire con gli attacchi in mischia aumentata del $s2% e probabilità che i nemici schivino i tuoi attacchi in mischia ridotta del $s1% mentre sei in Forma d'Orso, Forma felina o Forma d'Orso feroce. Non cumulabile con altre rune per anelli." },
    [442948] = { en = "A targeted party member is protected from all physical attacks for $d, but during that time they cannot attack or use physical abilities.  Players may only have one Blessing on them per Paladin at any one time.  Once protected, the target cannot be made invulnerable by Divine Shield, Divine Protection or Blessing of Protection again for $25771d.", description = "Un membro del gruppo selezionato è protetto da tutti gli attacchi fisici per $d, ma durante questo periodo non può attaccare né usare abilità fisiche. I giocatori possono avere una sola Benedizione per Paladino alla volta. Una volta protetto, il bersaglio non può essere reso invulnerabile di nuovo da Scudo divino, Protezione divina o Benedizione della protezione per $25771d." },
    [443265] = { en = "Deals $o1 Fire damage over $d. Demons and Beasts are Rooted in place for $1312052d.", description = "Infligge $o1 danni da Fuoco nell'arco di $d. Demoni e Bestie vengono immobilizzati sul posto per $1312052d." },
    [443278] = { en = "Chance to embed a seed into enemy humanoids, beasts, or dragonkin hit by your abilities or spells. If the creature is slain within 30 seconds of the seed being embedded, a Healing Blossom will grow from its corpse.\r\n", description = "Possibilità di far germogliare un seme negli umanoidi, nelle bestie o nei draconici nemici colpiti dalle tue abilità o dai tuoi incantesimi. Se la creatura viene uccisa entro 30 secondi dall'innesto del seme, dal suo cadavere crescerà un Fiore curativo.\r\n" },
    [443358] = { en = "Attack up to $i enemies within $a1 yards, causing weapon damage to each enemy, and reset the cooldown of your Whirlwind ability.", description = "Attacca fino a $i nemici entro $a1 metri, infliggendo danni da arma a ciascun nemico e azzerando il tempo di recupero della tua abilità Turbine." },
    [443631] = { en = "Grows a Healing Blossom with from the corpse of a humanoid or beast for $d that heals group members within $443464a1 yards for $443464s1 every $443464t1 seconds.", description = "Fa crescere un Fiore curativo dal cadavere di un umanoide o di una bestia per $d, che cura i membri del gruppo entro $443464a1 metri di $443464s1 ogni $443464t1 secondi." },
    [443917] = { en = "Blood fills the caster, granting $s1% of maximum mana every $t1 sec.", description = "Il sangue pervade l'incantatore, conferendo il $s1% del mana massimo ogni $t1 secondi." },
    [443953] = { en = "$@spelldesc443940", description = "$@spelldesc443940" },
    [443975] = { en = "$s1 Shadow damage inflicted every $t1 sec for $d.\r\nAttack, cast, and movement speed reduced by $s2% while this is in effect.", description = "Infligge $s1 danni da Ombra ogni $t1 secondi per $d.\r\nLa velocità d'attacco, di lancio e di movimento è ridotta del $s2% per la durata dell'effetto." },
    [443990] = { en = "Releases a fearsome howl, inflicting $s1 Shadow damage to all enemies and sending them fleeing in fear for $d.", description = "Emette un ululato terrificante, infliggendo $s1 danni da Ombra a tutti i nemici e facendoli fuggire terrorizzati per $d." },
    [444039] = { en = "Drives the target insane, turning them hostile to their allies and increasing their maximum health by $s1%.", description = "Fa impazzire il bersaglio, rendendolo ostile ai suoi alleati e aumentando la sua salute massima del $s1%." },
    [444046] = { en = "Forces nearby enemies to speak in Demonic, reducing their casting speed by $s1% for $d. ", description = "Costringe i nemici vicini a parlare in Demoniaco, riducendo la loro velocità di lancio del $s1% per $d. " },
    [444050] = { en = "Blasts players with blood, inflicting $s1 Shadow damage.", description = "Travolge i giocatori col sangue, infliggendo $s1 danni da Ombra." },
    [444165] = { en = "Drains the flesh and blood out of a target, turning them into a skeleton for $d. While under this effect, the target receives $s1% less healing and gains $2% increased movement speed.", description = "Prosciuga la carne e il sangue di un bersaglio, trasformandolo in uno scheletro per $d. Sotto questo effetto, il bersaglio riceve il $s1% di cure in meno e ottiene un aumento della velocità di movimento del $2%." },
    [444253] = { en = "Spits corrupted blood, inflicting $444261s1 Shadow damage every $444255t1 sec. This has a chance to spread to nearby players.", description = "Sputa sangue corrotto, infliggendo $444261s1 danni da Ombra ogni $444255t1 secondi. Può diffondersi ai giocatori vicini." },
    [444255] = { en = "$@spelldesc444253", description = "$@spelldesc444253" },
    [444261] = { en = "$@spelldesc444253", description = "$@spelldesc444253" },
