    [444291] = { en = "$@spelldesc444273", description = "$@spelldesc444273" },
    [445080] = { en = "Turns targets hostile to everyone. Killing another player causes the player to gain $445081s1% movement speed for $445081d.", description = "Rende i bersagli ostili a tutti. Uccidere un altro giocatore fa ottenere al giocatore un aumento della velocità di movimento del $445081s1% per $445081d." },
    [445081] = { en = "You killed another player! \r\nMovement speed increased by $s1% for $d.\r\n", description = "Hai ucciso un altro giocatore! \r\nVelocità di movimento aumentata del $s1% per $d.\r\n" },
    [445498] = { en = "Releases a shaking roar, sending all enemies within $A1 yards fleeing in fear for $d.", description = "Emette un ruggito fragoroso, facendo fuggire terrorizzati tutti i nemici entro $A1 metri per $d." },
    [445571] = { en = "$@spelldesc445575", description = "$@spelldesc445575" },
    [446088] = { en = "Restores $s1 mana per $t1 seconds. Removed in battlegrounds or dungeons.", description = "Ripristina $s1 mana ogni $t1 secondi. Rimosso nei campi di battaglia o nei dungeon." },
