    [446163] = { en = "Add $q2 Hi-Explosive Bombs to complete the shipment.", description = "Aggiungi $q2 Bombe ad alto potenziale per completare la spedizione." },
    [446164] = { en = "Add $q2 Thorium Grenades to complete the shipment.", description = "Aggiungi $q2 Granate di Torio per completare la spedizione." },
