    [446167] = { en = "Add $q2 Thorium Belts to complete the shipment.", description = "Aggiungi $q2 Cinture di Torio per completare la spedizione." },
    [446168] = { en = "Add $q2 Truesilver Gauntlets to complete the shipment.", description = "Aggiungi $q2 Guanti di Verargento per completare la spedizione." },
    [446171] = { en = "Add $q2 Rugged Armor Kits to complete the shipment.", description = "Aggiungi $q2 Rinforzi per armatura robusti per completare la spedizione." },
    [446172] = { en = "Add $q2 Wicked Leather Bracers to complete the shipment.", description = "Aggiungi $q2 Bracciali di cuoio malefico per completare la spedizione." },
    [446173] = { en = "Add $q2 Runic Leather Bracers to complete the shipment.", description = "Aggiungi $q2 Bracciali di cuoio runico per completare la spedizione." },
    [446174] = { en = "Add $q2 Black Mageweave Headbands to complete the shipment.", description = "Aggiungi $q2 Fasce nere di tessuto magico per la testa per completare la spedizione." },
    [446176] = { en = "Add $q2 Runecloth Belts to complete the shipment.", description = "Aggiungi $q2 Cinture di runotela per completare la spedizione." },
    [446177] = { en = "Add $q2 Tuxedo Shirts to complete the shipment.", description = "Aggiungi $q2 Camicie da smoking per completare la spedizione." },
    [446212] = { en = "Increases the duration of Rip by ${$s1/1000} sec.", description = "Aumenta la durata di Lacerare di ${$s1/1000} sec." },
    [446213] = { en = "Increases the block chance of your Holy Shield spell by $s1%.", description = "Aumenta la probabilità di parata del tuo incantesimo Scudo Sacro del $s1%." },
    [446219] = { en = "Increases attack power, spell damage, and healing by $s1.\r\n", description = "Aumenta la potenza d'attacco, i danni degli incantesimi e le cure di $s1.\r\n" },
    [446220] = { en = "Flame Shock grants $446219s1 attack power, spell damage, and healing for $446219d1.", description = "Fol shock conferisce $446219s1 potenza d'attacco, danni degli incantesimi e cure per $446219d1." },
    [446256] = { en = "Increases spell power by $s1. Successful spell hits have a chance to unleash a Shadow Bolt on the target. Only one type of Atal'ai potion may be active at any given time. This has no effect outside of Sunken Temple.", description = "Aumenta la potenza magica di $s1. I colpi riusciti degli incantesimi hanno una probabilità di scagliare un Dardo d'Ombra sul bersaglio. Può essere attivo un solo tipo di pozione Atal'ai alla volta. Non ha effetto al di fuori del Tempio Sommerso." },
    [446265] = { en = "$@spelldesc445575", description = "$@spelldesc445575" },
    [446297] = { en = "Increases your spell damage by up to 96 and your healing by up to 192 for $d. Every time you cast a spell, the bonus is reduced by 8 spell damage and 16 healing.", description = "Aumenta i danni degli incantesimi fino a 96 e le cure fino a 192 per $d. Ogni volta che lanci un incantesimo, il bonus si riduce di 8 ai danni degli incantesimi e di 16 alle cure." },
    [446310] = { en = "Increases your armor by 1000 and defense skill by 20 for $d. Every time you take melee or ranged damage, this bonus is reduced by 100 armor and 2 defense.", description = "Aumenta l'armatura di 1000 e l'abilità Difesa di 20 per $d. Ogni volta che subisci danni in mischia o a distanza, questo bonus si riduce di 100 all'armatura e di 2 alla Difesa." },
    [446336] = { en = "Increases melee and ranged attack power by $s1. Chance on melee or ranged attack to grow in size, increasing Strength or Agility (whichever is higher) by $446335s1 for $446335d. Only one type of Atal'ai potion may be active at any given time. This has no effect outside of Sunken Temple.", description = "Aumenta la potenza d'attacco in mischia e a distanza di $s1. Gli attacchi in mischia o a distanza hanno una probabilità di aumentare la tua taglia, incrementando la Forza o l'Agilità (a seconda di quale sia più alta) di $446335s1 per $446335d. Può essere attivo un solo tipo di pozione Atal'ai alla volta. Non ha effetto al di fuori del Tempio Sommerso." },
    [446382] = { en = "Channels the power of the Void, granting immunity to Fear for $d.", description = "Canalizza il potere del Vuoto, conferendo immunità alla Paura per $d." },
    [446396] = { en = "Increases healing done by $s1, mana regeneration by $s2 mana per 5 sec, and your heals have a chance to restore $446785s1 Energy, $446786s1% Mana, or $/10;446783s1 Rage. Only one Atal'ai potion can be active at any time. This has no effect outside of Sunken Temple.", description = "Aumenta le cure effettuate di $s1, la rigenerazione del mana di $s2 mana ogni 5 sec. e le tue cure hanno una probabilità di ripristinare $446785s1 energia, $446786s1% mana oppure $/10;446783s1 rabbia. Può essere attiva una sola pozione Atal'ai alla volta. Non ha effetto al di fuori del Tempio Sommerso." },
    [446518] = { en = "Damaging spells have a chance to increase your spell casting speed by $s1% for $446528d. This has no effect outside of areas under the influence of the Nightmare.", description = "Gli incantesimi che infliggono danni hanno una probabilità di aumentare la velocità di lancio degli incantesimi del $s1% per $446528d. Non ha effetto al di fuori delle aree sotto l'influenza dell'Incubo." },
    [446528] = { en = "Echoes from the void drive you to madness. Increasing your spell casting speed by $s1%.  This has no effect outside of areas under the influence of the Nightmare.", description = "Gli echi del Vuoto ti spingono alla follia. Aumenta la velocità di lancio degli incantesimi del $s1%.  Non ha effetto al di fuori delle aree sotto l'influenza dell'Incubo." },
    [446541] = { en = "Echoes from the void drive you to insanity. Increasing your healing by up to $s1.  This has no effect outside of areas under the influence of the Nightmare.", description = "Gli echi del Vuoto ti spingono alla follia. Aumenta le tue cure fino a $s1.  Non ha effetto al di fuori delle aree sotto l'influenza dell'Incubo." },
    [446545] = { en = "Healing spells have a chance to increase your healing by up to $s1 for $446541d.  This has no effect outside of areas under the influence of the Nightmare.", description = "Gli incantesimi di cura hanno una probabilità di aumentare le tue cure fino a $s1 per $446541d.  Non ha effetto al di fuori delle aree sotto l'influenza dell'Incubo." },
    [446570] = { en = "Damaging spells have a chance to increase your spell damage by $446572s1 and chance to dodge by $446572s2% for $446572d.  This has no effect outside of areas under the influence of the Nightmare.", description = "Gli incantesimi che infliggono danni hanno una probabilità di aumentare i danni degli incantesimi di $446572s1 e la probabilità di schivata del $446572s2% per $446572d.  Non ha effetto al di fuori delle aree sotto l'influenza dell'Incubo." },
    [446572] = { en = "Echoes from the void corrupt your thoughts. Increasing your spell damage by $446572s1 and chance to dodge by $446572s2%.  This has no effect outside of areas under the influence of the Nightmare.", description = "Gli echi del Vuoto corrompono i tuoi pensieri. Aumenta i danni degli incantesimi di $446572s1 e la probabilità di schivata del $446572s2%.  Non ha effetto al di fuori delle aree sotto l'influenza dell'Incubo." },
    [446577] = { en = "Your melee attacks have a chance to unleash echoes from the void, instilling you with a deep sense of dread. Increasing your attack speed by $446577s1% and attack power by $446577s2.  This has no effect outside of areas under the influence of the Nightmare.", description = "I tuoi attacchi in mischia hanno una probabilità di sprigionare echi del Vuoto, instillandoti un profondo senso di terrore. Aumenta la velocità d'attacco del $446577s1% e la potenza d'attacco di $446577s2.  Non ha effetto al di fuori delle aree sotto l'influenza dell'Incubo." },
    [446579] = { en = "Melee attacks have a chance to increase your attack speed by $446577s1% and attack power by $446577s2 for $446577d.  This has no effect outside of areas under the influence of the Nightmare.", description = "Gli attacchi in mischia hanno una probabilità di aumentare la velocità d'attacco del $446577s1% e la potenza d'attacco di $446577s2 per $446577d.  Non ha effetto al di fuori delle aree sotto l'influenza dell'Incubo." },
    [446592] = { en = "Melee attacks and harmful spells have a chance to increase spell damage by up to $446597s1 for $446597d.  This has no effect outside of areas under the influence of the Nightmare.", description = "Gli attacchi in mischia e gli incantesimi nocivi hanno una probabilità di aumentare i danni degli incantesimi fino a $446597s1 per $446597d.  Non ha effetto al di fuori delle aree sotto l'influenza dell'Incubo." },
    [446597] = { en = "Your melee attacks and harmful spells have a chance to unleash echoes from the void, instilling you with fear. Increasing your spell damage by $446597s1.  This has no effect outside of areas under the influence of the Nightmare.", description = "I tuoi attacchi in mischia e gli incantesimi nocivi hanno una probabilità di sprigionare echi del Vuoto, instillandoti paura. Aumenta i danni degli incantesimi di $446597s1.  Non ha effetto al di fuori delle aree sotto l'influenza dell'Incubo." },
    [446618] = { en = "Melee and ranged attacks have a chance to increase your attack power by $s2.  This has no effect outside of areas under the influence of the Nightmare.", description = "Gli attacchi in mischia e a distanza hanno una probabilità di aumentare la tua potenza d'attacco di $s2.  Non ha effetto al di fuori delle aree sotto l'influenza dell'Incubo." },
    [446620] = { en = "Melee and ranged attacks have a chance to increase your attack power by $446618s2 for $446618d.  This has no effect outside of areas under the influence of the Nightmare.", description = "Gli attacchi in mischia e a distanza hanno una probabilità di aumentare la tua potenza d'attacco di $446618s2 per $446618d.  Non ha effetto al di fuori delle aree sotto l'influenza dell'Incubo." },
    [446628] = { en = "Melee attacks have a chance to increase your attack power by $446630s1 and chance to dodge by $446630s2%.  This has no effect outside of areas under the influence of the Nightmare.", description = "Gli attacchi in mischia hanno una probabilità di aumentare la tua potenza d'attacco di $446630s1 e la probabilità di schivata del $446630s2%.  Non ha effetto al di fuori delle aree sotto l'influenza dell'Incubo." },
    [446630] = { en = "Melee attacks have a chance to increase your attack power by $446572s1 and chance to dodge by $446572s2%.  This has no effect outside of areas under the influence of the Nightmare.", description = "Gli attacchi in mischia hanno una probabilità di aumentare la tua potenza d'attacco di $446572s1 e la probabilità di schivata del $446572s2%.  Non ha effetto al di fuori delle aree sotto l'influenza dell'Incubo." },
    [446675] = { en = "Restores $446677s1 health and mana when you kill a target that gives experience or honor. This effect cannot occur more than once every 10 seconds.", description = "Ripristina $446677s1 salute e mana quando uccidi un bersaglio che fornisce esperienza o onore. Questo effetto non può attivarsi più di una volta ogni 10 secondi." },
