    [446687] = { en = "Increases the damage or healing of your next attack, ability, or spell by $s1.", description = "Aumenta i danni o le cure del tuo prossimo attacco, abilità o incantesimo di $s1." },
    [446689] = { en = "Increases the damage or healing of your next attack, ability, or spell by $446687s1 when you kill a target that gives experience or honor. This effect cannot occur more than once every 10 seconds.", description = "Aumenta i danni o le cure del tuo prossimo attacco, abilità o incantesimo di $446687s1 quando uccidi un bersaglio che fornisce esperienza o onore. Questo effetto non può attivarsi più di una volta ogni 10 secondi." },
