    [447581] = { en = "$@spelldesc998", description = "$@spelldesc998" },
    [448246] = { en = "$@spelldesc445575", description = "$@spelldesc445575" },
    [448686] = { en = "Increases the damage of your next non-channeled Affliction based damage over time spell by $s1%.", description = "Aumenta del $s1% i danni del tuo prossimo effetto di danno periodico basato su Afflizione non canalizzato." },
    [449432] = { en = "Curses the target with impending doom, causing $s1 Shadow damage after $d.  If the target dies from this damage, there is a chance that a Doomguard will be summoned.  Cannot be cast on players.", description = "Maledice il bersaglio con una rovina imminente, infliggendo $s1 danni d'Ombra dopo $d.  Se il bersaglio muore a causa di questi danni, c'è una probabilità che venga evocato un Guardiano del Destino.  Non può essere lanciato sui giocatori." },
    [449927] = { en = "Causes the target to hemorrhage, increasing any damage dealt to the target by up to $s1.  Lasts $n charges or $d.", description = "Fa emorragia al bersaglio, aumentando fino a $s1 tutti i danni inflitti al bersaglio.  Dura $n cariche o $d." },
    [449928] = { en = "Backstab and Sinister Strike cause the target to take $449927s1 more damage from all sources for $449927n charges or $449927d.", description = "Pugnalata alle spalle e Colpo Sinistro fanno sì che il bersaglio subisca $449927s1 danni aggiuntivi da tutte le fonti per $449927n cariche o $449927d." },
    [449929] = { en = "Your direct healing spell critical strikes now have a $h% chance to activate Dreamstate. You must have the rune engraved.", description = "I colpi critici diretti dei tuoi incantesimi di cura ora hanno una probabilità del $h% di attivare Stato Onirico. Devi avere la runa incisa." },
    [449930] = { en = "Reduces the cast time of Healing Rain by $s1%.", description = "Riduce il tempo di lancio di Pioggia Curativa del $s1%." },
    [449931] = { en = "Dealing Fire damage causes you to gain $449932s1 attack power, stacking up to $449932u times. Lasts $449932d.", description = "Infliggere danni da Fuoco ti conferisce $449932s1 potenza d'attacco, cumulabile fino a $449932u volte. Dura $449932d." },
    [449934] = { en = "Increases damage and healing done by Nature spells and effects by up to $s1.", description = "Aumenta i danni e le cure degli incantesimi e degli effetti di Natura fino a $s1." },
    [449935] = { en = "Chance on spell cast to increase your Nature spell damage and healing by up to $449934s1 for $449934d.", description = "Quando lanci un incantesimo, hai una probabilità di aumentare i danni e le cure degli incantesimi di Natura fino a $449934s1 per $449934d." },
    [449974] = { en = "Gain $449975s1 block value for $449975d after blocking.", description = "Ottieni $449975s1 punti di blocco per $449975d dopo aver bloccato." },
    [449980] = { en = "Causes Holy Shock to reduce the cast time of your next Holy Light cast within $449982d by ${$449982m1/-1000}.1 sec.", description = "Consacrazione riduce il tempo di lancio del tuo prossimo lancio di Luce Sacra entro $449982d di ${$449982m1/-1000}.1 sec." },
    [449982] = { en = "Holy Light cast time reduced by ${$m1/1000}.1 sec.", description = "Tempo di lancio di Luce Sacra ridotto di ${$m1/1000}.1 sec." },
