    [450587] = { en = "Chance on melee attack to heal for $450589s1 and generate ${$450589m2/10} Rage", description = "Probabilità all'attacco in mischia di curare di $450589s1 e generare ${$450589m2/10} rabbia" },
    [450608] = { en = "Chance on spellcast to restore $27782s1 Mana, on melee attack to regenerate $27784o1 Energy over $27784d, and when struck by a melee attack to generate ${$27783s1/10} Rage.", description = "Probabilità al lancio di un incantesimo di ripristinare $27782s1 mana, all'attacco in mischia di rigenerare $27784o1 energia in $27784d e, quando colpito da un attacco in mischia, di generare ${$27783s1/10} rabbia." },
    [451439] = { en = "Damaging finishing moves have a $b1% chance per combo point to restore $451438s1 energy.", description = "Le mosse finali che infliggono danni hanno una probabilità del $b1% per punto combo di ripristinare $451438s1 energia." },
